                    let position =
                        Vec3::new(p.position.x / 20., p.height / 20., p.position.z / 20.);
                    if !state.visuals.contains_key(&p.id) {
                        let (request, scale) =
                            animation::request(p.id, &p.champion, &catalog, &assets);
